$ok = 0; $fail = 0
foreach ($d in $downloads) {
  $out = Join-Path $dest $d.Name
  try {
    Invoke-WebRequest -Uri $d.Url -OutFile $out -Headers $h -UseBasicParsing -TimeoutSec 30
    Write-Host "OK  $($d.Name)"
    $ok++
  } catch {
    Write-Host "FAIL $($d.Name): $_"
    $fail++
  }
}
Write-Host "`nDone: $ok OK, $fail failed"
